<script setup lang="ts">
definePageMeta({ middleware: ['cms-auth', 'cms-admin'] })
const { csrfHeaders } = useCmsSession(); const { data, refresh } = await useFetch<any>('/api/cms/member-applications'); const note = ref(''); const message = ref(''); const errorMessage = ref('')
const review = async (id: string, action: 'approve' | 'reject') => { if (!confirm(action === 'approve' ? '审核通过后将立即创建正式成员并上线，确定吗？' : '拒绝后将删除临时头像，确定吗？')) return; try { await $fetch(`/api/cms/member-applications/${id}/review`, { method: 'POST', headers: csrfHeaders(), body: { action, note: note.value } }); message.value = action === 'approve' ? '已审核通过并上线' : '已拒绝并清理临时头像'; await refresh() } catch (error: any) { errorMessage.value = error?.data?.message || '审核失败' } }
</script>
<template><section class="cms-page"><header class="cms-page-header"><div><p class="cms-eyebrow">MEMBER REVIEW</p><h1>成员信息审核</h1><p>只有这里明确审核通过后，申请才会创建正式 Revision 并上线。</p></div></header><p v-if="message" class="cms-alert">{{ message }}</p><p v-if="errorMessage" class="cms-alert cms-alert-error">{{ errorMessage }}</p><label class="cms-form"><span>审核备注</span><textarea v-model="note" rows="3" maxlength="1000" /></label><section v-for="item in data?.applications" :key="item.id" class="cms-panel"><img v-if="item.avatarPublicUrl" class="cms-member-avatar" :src="item.avatarPublicUrl" alt="申请头像"><h2>{{ item.profile.name }}</h2><pre>{{ JSON.stringify(item.profile, null, 2) }}</pre><button class="cms-button cms-button-primary" @click="review(item.id, 'approve')">审核通过并上线</button><button class="cms-button" @click="review(item.id, 'reject')">拒绝</button></section><p v-if="!data?.applications.length" class="cms-muted">暂无待审核申请。</p></section></template>
